    // Variance = [(-1+(-2)+(-3))/3 = -2, then [(-1+2)^2 + (-2+2)^2 + (-3+2)^2] / (3-1) = [1 + 0 + 1] / 2 = 1.0
    Assert.assertEquals(1.0, result, 1e-10);
