public class LLMGeneratedTests {

private Vector3D p3;
private Vector3D p2;
private Vector3D direction;
private Vector3D zero;
private Vector3D p1;
private Line line;
private Vector3D p4;

@Before
    public void setUp() throws Exception {
        // Set up test data
        p1 = new Vector3D(1.0, 2.0, 3.0);
        p2 = new Vector3D(4.0, 5.0, 1.0);
        direction = p2.subtract(p1).normalize();
        zero = p1;
        line = new Line(p1, p2);
    }


@Test
    public void testRevertWithDifferentPoints() {
        // Test revert with different points
        Vector3D differentP1 = new Vector3D(1.0, 2.0, 3.0);
        Vector3D differentP2 = new Vector3D(5.0, 6.0, 7.0);
        Line differentLine = new Line(differentP1, differentP2);
        Line revertedDifferent = differentLine.revert();
        Vector3D revertedDifferentDirection = revertedDifferent.getDirection();
        Vector3D expectedDifferentDirection = differentLine.getDirection().negate();
        Assert.assertEquals(expectedDifferentDirection, revertedDifferentDirection);
        Vector3D revertedDifferentZero = revertedDifferent.getOrigin();
        Assert.assertEquals(differentP1, revertedDifferentZero);
    }


@Test
    public void testRevert() {
        // Test revert method
        Line reverted = line.revert();
        // Check direction is negated
        Vector3D revertedDirection = reverted.getDirection();
        Vector3D expectedDirection = direction.negate();
        Assert.assertEquals(expectedDirection, revertedDirection);
        // Check origin is the same
        Vector3D revertedZero = reverted.getOrigin();
        Assert.assertEquals(zero, revertedZero);
    }


@Test
    public void testRevertWithSamePoints() {
        // Test revert with same points
        Vector3D sameP1 = new Vector3D(1.0, 2.0, 3.0);
        Vector3D sameP2 = new Vector3D(4.0, 5.0, 1.0);
        Line sameLine = new Line(sameP1, sameP2);
        Line revertedSame = sameLine.revert();
        Vector3D revertedSameDirection = revertedSame.getDirection();
        Vector3D expectedSameDirection = sameLine.getDirection().negate();
        Assert.assertEquals(expectedSameDirection, revertedSameDirection);
        Vector3D revertedSameZero = revertedSame.getOrigin();
        Assert.assertEquals(sameP1, revertedSameZero);
    }

}
